insert into public.products (
  brand_id, slug, title_zh_hk, title_zh_cn, title_en,
  description_zh_hk, description_zh_cn, description_en,
  price_hkd, stock, image_paths, status, sort
)
select b.id, x.slug, x.title_zh_hk, x.title_zh_cn, x.title_en,
  x.description_zh_hk, x.description_zh_cn, x.description_en,
  x.price_hkd, x.stock, x.image_paths, 'on_sale', x.sort
from jsonb_to_recordset($json$[{"brand_slug":"dermaquest","slug":"b5-intensive-concentrate-serum","title_zh_hk":"B5\u7279\u6548\u6fc3\u7e2e\u7cbe\u83ef","title_zh_cn":"B5\u7279\u6548\u6d53\u7f29\u7cbe\u534e","title_en":"B5 Intensive Concentrate Serum","description_zh_hk":"<p class=\"p1\"><b>B5\u7279\u6548\u6fc3\u7e2e\u7cbe\u83ef</b></p>\n<p class=\"p2\">\u9069\u5408\u6240\u6709\u808c\u819a</p>\n<p class=\"p2\"><b>\u529f\u6548</b></p>\n<ul class=\"ul1\">\n<li class=\"li2\">\u9396\u7dca\u6c34\u5206\u65bc\u808c\u819a\u5e95\uff0c\u6539\u5584\u5929\u7136\u4fdd\u6fd5\u80fd\u529b</li>\n<li class=\"li2\">\u4fc3\u9032\u808c\u819a\u7d30\u80de\u518d\u751f\uff0c\u6e1b\u5c11\u7d30\u7d0b\u53ca\u76ba\u7d0b</li>\n<li class=\"li2\">\u4ee5\u5c08\u5229\u6ef2\u900f\u6280\u8853\uff0c\u4f7f\u7cbe\u83ef\u80fd\u8fc5\u901f\u6ef2\u900f\u81f3\u76ae\u819a\u5e95\u5c64\uff0c\u9ad8\u6548\u4fdd\u6fd5\uff0c\u808c\u819a\u5373\u6642\u56de\u5fa9\u5f48\u6027\u3001\u7dca\u7dfb\u3001\u4eae\u6fa4\u3002\u91ab\u5b78\u7d1a\u7684B5 \u7279\u6548\u6fc3\u7e2e\u7cbe\u83ef\u9069\u7528\u65bc\u4efb\u4f55\u808c\u819a\u3002\u4e3b\u8981\u529f\u6548\n<p>\u2013 \u9396\u7dca\u6c34\u5206\u65bc\u808c\u819a\u5e95\u5c64\uff0c\u6539\u5584\u5929\u7136\u4fdd\u6fd5\u80fd\u529b</p>\n<p>\u2013 \u4fc3\u9032\u808c\u819a\u7d30\u80de\u518d\u751f\uff0c\u6e1b\u5c11\u7d30\u7d0b\u53ca\u76ba\u7d0b</p>\n<p>\u2013 \u63d0\u5347\u808c\u819a\u7dca\u7dfb\u5ea6\u3001\u67d4\u8edf\u5ea6\u53ca\u5f48\u6027</p>\n\n<p>\u4e3b\u8981\u6210\u4efd<br />\n\u2013 \u900f\u660e\u8cea\u9178\u9209 \u2013 40%</p>\n<p>\u2013 \u7dad\u4ed6\u547dB5</p>\n<p>\u2013 \u6d77\u6d0b\u9175\u7d20</p>\n<p>\u2013 Actifirm TS</li>\n</ul>","description_zh_cn":"<p class=\"p1\"><b>B5\u7279\u6548\u6d53\u7f29\u7cbe\u534e</b></p>\n<p class=\"p2\">\u9002\u5408\u6240\u6709\u808c\u80a4</p>\n<p class=\"p2\"><b>\u529f\u6548</b></p>\n<ul class=\"ul1\">\n<li class=\"li2\">\u9501\u7d27\u6c34\u5206\u4e8e\u808c\u80a4\u5e95\uff0c\u6539\u5584\u5929\u7136\u4fdd\u6e7f\u80fd\u529b</li>\n<li class=\"li2\">\u4fc3\u8fdb\u808c\u80a4\u7ec6\u80de\u518d\u751f\uff0c\u51cf\u5c11\u7ec6\u7eb9\u53ca\u76b1\u7eb9</li>\n<li class=\"li2\">\u4ee5\u4e13\u5229\u6e17\u900f\u6280\u672f\uff0c\u4f7f\u7cbe\u534e\u80fd\u8fc5\u901f\u6e17\u900f\u81f3\u76ae\u80a4\u5e95\u5c42\uff0c\u9ad8\u6548\u4fdd\u6e7f\uff0c\u808c\u80a4\u5373\u65f6\u56de\u590d\u5f39\u6027\u3001\u7d27\u81f4\u3001\u4eae\u6cfd\u3002\u533b\u5b66\u7ea7\u7684B5 \u7279\u6548\u6d53\u7f29\u7cbe\u534e\u9002\u7528\u4e8e\u4efb\u4f55\u808c\u80a4\u3002\u4e3b\u8981\u529f\u6548\n<p>\u2013 \u9501\u7d27\u6c34\u5206\u4e8e\u808c\u80a4\u5e95\u5c42\uff0c\u6539\u5584\u5929\u7136\u4fdd\u6e7f\u80fd\u529b</p>\n<p>\u2013 \u4fc3\u8fdb\u808c\u80a4\u7ec6\u80de\u518d\u751f\uff0c\u51cf\u5c11\u7ec6\u7eb9\u53ca\u76b1\u7eb9</p>\n<p>\u2013 \u63d0\u5347\u808c\u80a4\u7d27\u81f4\u5ea6\u3001\u67d4\u8f6f\u5ea6\u53ca\u5f39\u6027</p>\n\n<p>\u4e3b\u8981\u6210\u4efd<br />\n\u2013 \u900f\u660e\u8d28\u9178\u94a0 \u2013 40%</p>\n<p>\u2013 \u7ef4\u4ed6\u547dB5</p>\n<p>\u2013 \u6d77\u6d0b\u9175\u7d20</p>\n<p>\u2013 Actifirm TS</li>\n</ul>","description_en":"<p>Suitable for all skin types</p>\n<p>Locks moisture into the skin, supports cell renewal and reduces fine lines. Patented penetration delivers hydration so skin feels elastic, firm and radiant.</p>\n<p>Key benefits</p>\n<p>\u2013 Locks in moisture and improves natural hydration</p>\n<p>\u2013 Supports cell renewal and reduces fine lines</p>\n<p>\u2013 Improves firmness, softness and elasticity</p>\n<p>Key ingredients</p>\n<p>\u2013 Sodium hyaluronate 40%</p>\n<p>\u2013 Vitamin B5</p>\n<p>\u2013 Marine enzymes</p>\n<p>\u2013 Actifirm TS</p>","price_hkd":790,"stock":20,"image_paths":["/images/products/prod-4@2x.jpg"],"sort":226}]$json$::jsonb) as x(
  brand_slug text, slug text, title_zh_hk text, title_zh_cn text, title_en text,
